def table(metric,suffix=''):
 rows=['| Response | Original | Fixed PISCO | Fixed PISCO + KFM/LTER |','|---|---:|---:|---:|']
 for tx,r,label in order:
  vals=[]
  for s in scenarios:
   q=p[(p.scenario==s+suffix)&(p.metric==metric)&(p.Taxa==tx)&(p.Resp==r)]
   if q.empty:vals.append('Not estimated');continue
   q=q.iloc[0]
   if metric=='Post_slope':vals.append(f'{convert(q.estimate):+.1f}%'+(f' ({convert(q.low):+.1f}, {convert(q.high):+.1f})' if np.isfinite(q.low) else ' (interval not supported)'))
   else:vals.append(f'{np.exp(q.estimate):.2f}×'+(f' ({np.exp(q.low):.2f}, {np.exp(q.high):.2f})' if np.isfinite(q.low) else ' (interval not supported)'))
  rows.append('| '+label+' | '+' | '.join(vals)+' |')
 return '\n'.join(rows)
